151	func TestConcurrentRegisterDistinctVersions(t *testing.T) {
152		dir := t.TempDir()
153		done := make(chan error, 8)
154		for i := 0; i < 8; i++ {
155			go func(i int) {
156				spec := fmt.Sprintf(`{"id":"v%d","rules":{"sandwich":{"enabled":true,"severity":%d},"displacement":{"enabled":true,"severity":2,"multiplier":%d}}}`,
157					i, i%5+1, i%99+2)
158				// A busy archive is a valid answer to a concurrent writer; retry
159				// until the registration commits.
160				for {
161					_, _, err := RegisterVersion(dir, []byte(spec))
162					if errors.Is(err, ErrBusy) {
163						continue
164					}
165					done <- err
166					return
167				}
168			}(i)
169		}
170		for i := 0; i < 8; i++ {
171			if err := <-done; err != nil {
172				t.Fatalf("concurrent register: %v", err)
173			}
174		}
175		versions, _, err := ListVersions(dir)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if len(versions) != 9 { // builtin + 8 registered
180			t.Fatalf("got %d versions, want 9; concurrent writes lost data", len(versions))
181		}
